/**
 * Returns the BoPoMoFo (注音) transcription for a single Chinese character.
 */
export function getZhuyinForChar(char: string): string {
  if (!char) return '';
  return ZHUYIN_DICTIONARY[char] || '';
}

/**
 * Returns an array of BoPoMoFo (注音) transcriptions for each character in a Chinese word/phrase.
 */
export function getZhuyinForWord(word: string): string[] {
  if (!word) return [];
  return Array.from(word).map((char) => getZhuyinForChar(char));
}
